import { RobotModel } from '../../types/robot';
import { CodeExportOptions } from '../../types/codeExport';
import { PUMA560_INERTIA } from '../../physics/RNEEngine';

export function generateMatlabCode(
  robot: RobotModel,
  currentAnglesDeg: number[],
  options: CodeExportOptions
): string {
  const qDegStr = currentAnglesDeg.map((a) => a.toFixed(2)).join(', ');

  let code = `% =========================================================================
% MATLAB Robotics System Toolbox & SerialLink Script
% Robot Model: ${robot.name} (${robot.manufacturer}) - ${robot.dof} DOF
% Generated by RoboCAD 3D - Multi-Platform Code Exporter
% =========================================================================
% Requirements:
%   - MATLAB R2019b or newer
%   - Robotics System Toolbox (or Peter Corke Robotics Toolbox)
% =========================================================================

clear; clc; close all;

fprintf('=========================================================\\n');
fprintf('MATLAB Robotics System Toolbox: %s\\n', '${robot.name}');
fprintf('=========================================================\\n');

%% 1. Create rigidBodyTree Model
robot = rigidBodyTree('DataFormat', 'row', 'MaxNumBodies', ${robot.dof + 5});
robot.Gravity = [0, 0, -9.81];

% Denavit-Hartenberg Parameters Table:
% [a (m), alpha (rad), d (m), theta_offset (rad)]
dh_table = [
`;

  robot.joints.forEach((joint, idx) => {
    const aMeters = (joint.a / 1000).toFixed(5);
    const alphaRad = ((joint.alphaDeg * Math.PI) / 180).toFixed(5);
    const dMeters = (joint.d / 1000).toFixed(5);
    const thetaOffsetRad = ((joint.thetaOffsetDeg * Math.PI) / 180).toFixed(5);
    code += `    ${aMeters}, ${alphaRad}, ${dMeters}, ${thetaOffsetRad}; % Joint ${idx + 1}\n`;
  });

  code += `];

% Joint Limits [lower_rad, upper_rad]
joint_limits = [
`;

  robot.joints.forEach((joint, idx) => {
    const qMinRad = ((joint.qMinDeg * Math.PI) / 180).toFixed(4);
    const qMaxRad = ((joint.qMaxDeg * Math.PI) / 180).toFixed(4);
    code += `    ${qMinRad}, ${qMaxRad}; % Joint ${idx + 1}\n`;
  });

  code += `];

%% 2. Assemble Rigid Bodies
parentName = robot.BaseName;

for i = 1:${robot.dof}
    bodyName = sprintf('link_%d', i);
    jointName = sprintf('joint_%d', i);
    
    body = rigidBody(bodyName);
    jnt = rigidBodyJoint(jointName, 'revolute');
    
    % Set DH parameters: [a, alpha, d, theta_offset]
    setFixedTransform(jnt, dh_table(i, :), 'dh');
    jnt.PositionLimits = joint_limits(i, :);
    jnt.JointAxis = [0, 0, 1];
`;

  if (options.includeDynamics) {
    code += `
    % Inertial Properties
`;
    robot.joints.forEach((joint, idx) => {
      const inertia =
        robot.id === 'Puma560' && PUMA560_INERTIA[idx]
          ? PUMA560_INERTIA[idx]
          : {
              mass: (robot.totalWeightKg / robot.dof) * (1 - idx * 0.12),
              com: [0, 0, joint.d / 2000],
              inertia: [[0.05, 0, 0], [0, 0.05, 0], [0, 0.05, 0]],
            };

      const m = inertia.mass.toFixed(3);
      const com = `[${inertia.com.map((c) => c.toFixed(3)).join(', ')}]`;
      const Ivec = `[${inertia.inertia[0][0].toFixed(5)}, ${inertia.inertia[1][1].toFixed(5)}, ${inertia.inertia[2][2].toFixed(5)}, 0, 0, 0]`;

      code += `    if i == ${idx + 1}
        body.Mass = ${m};
        body.CenterOfMass = ${com};
        body.Inertia = ${Ivec}; % [Ixx Iyy Izz Iyz Ixz Ixy]
    end
`;
    });
  }

  code += `
    body.Joint = jnt;
    addBody(robot, body, parentName);
    parentName = bodyName;
end

% Add End-Effector Tool Flange
toolBody = rigidBody('tool0');
toolJoint = rigidBodyJoint('tool_fixed', 'fixed');
setFixedTransform(toolJoint, eye(4));
toolBody.Joint = toolJoint;
addBody(robot, toolBody, parentName);

disp('Robot tree assembly completed successfully:');
showdetails(robot);

%% 3. Configuration & Kinematic Computations
`;

  if (options.useCurrentAngles) {
    code += `% Active Joint Angles from Simulation:
q_deg = [${qDegStr}];
q = deg2rad(q_deg);
`;
  } else {
    code += `% Home Configuration:
q = homeConfiguration(robot);
q_deg = rad2deg(q);
`;
  }

  code += `
fprintf('\\nEvaluating at Joint Configuration:\\n');
for i = 1:${robot.dof}
    fprintf('  Joint %d: %8.2f deg (%8.4f rad)\\n', i, q_deg(i), q(i));
end
`;

  if (options.includeKinematics) {
    code += `
%% 4. Forward Kinematics (FK)
T_tcp = getTransform(robot, q, 'tool0');
fprintf('\\n[1] Forward Kinematics Matrix T (4x4):\\n');
disp(T_tcp);

tcp_pos_m = T_tcp(1:3, 4)';
fprintf('TCP Position (X, Y, Z) in meters: [%.4f, %.4f, %.4f]\\n', tcp_pos_m);
fprintf('TCP Position in mm:                [%.1f, %.1f, %.1f]\\n', tcp_pos_m * 1000);
`;
  }

  if (options.includeJacobian) {
    code += `
%% 5. Geometric Jacobian & Manipulability
J = geometricJacobian(robot, q, 'tool0');
fprintf('\\n[2] Geometric Jacobian Matrix (6x%d) at current q:\\n', ${robot.dof});
disp(J);

% Manipulability measure (Yoshikawa)
w = sqrt(det(J * J'));
fprintf('Yoshikawa Manipulability Measure w: %.6f\\n', w);
`;
  }

  if (options.includeDynamics) {
    code += `
%% 6. Inverse Dynamics (Newton-Euler)
qd = zeros(1, ${robot.dof});  % Joint velocities
qdd = zeros(1, ${robot.dof}); % Joint accelerations

% Gravity load tau_g
tau_g = gravityTorque(robot, q);
fprintf('\\n[3] Static Gravity Holding Torques g(q) [N.m]:\\n');
for i = 1:${robot.dof}
    fprintf('  Joint %d: %+8.2f N.m\\n', i, tau_g(i));
end

% Mass matrix M(q)
M = massMatrix(robot, q);
fprintf('\\nMass Matrix M(q) (6x6):\\n');
disp(M);

% Dynamic torques under motion
qd_test = ones(1, ${robot.dof}) * 0.5;
qdd_test = ones(1, ${robot.dof}) * 1.0;
tau_dyn = inverseDynamics(robot, q, qd_test, qdd_test);
fprintf('\\nDynamic Torques tau = M*qdd + C*qd + g [N.m]:\\n');
disp(tau_dyn);
`;
  }

  if (options.includeVisualization) {
    code += `
%% 7. 3D Robot Visualization
figure('Name', '${robot.name} 3D Viewport', 'Color', 'w');
show(robot, q, 'PreservePlot', false, 'Frames', 'on', 'Visuals', 'on');
title(sprintf('${robot.name} Kinematic Pose [w = %.4f]', ${options.includeJacobian ? 'w' : '0.0'}));
grid on; axis equal;
view(135, 30);
camlight;
lighting gouraud;
`;
  }

  return code;
}
